#pragma once

#include <stddef.h>
#include <stdint.h>

constexpr size_t UUID_BYTE_SIZE   = 16U;
constexpr size_t UUID_STRING_SIZE = 37U;

typedef struct uuid_t
{
    uint8_t bytes[UUID_BYTE_SIZE];
} uuid_t;

typedef struct uuid_str_t
{
    char str[UUID_STRING_SIZE];
} uuid_str_t;

// =========================================================================================================================================
// =========================================================================================================================================
// uuid_is_nil_z: Check if a UUID is nil (all bytes equal to SENTINEL value).
// =========================================================================================================================================
// =========================================================================================================================================
bool uuid_is_nil_z(const uuid_t uuid);

// =========================================================================================================================================
// =========================================================================================================================================
// uuid_nil_z: Create a nil UUID with all bytes set to SENTINEL value.
// =========================================================================================================================================
// =========================================================================================================================================
uuid_t uuid_nil_z();

// =========================================================================================================================================
// =========================================================================================================================================
// uuid_format_z: Format a UUID into its standard string representation (xxxxxxxx-xxxx-xxxx-xxxx-xxxxxxxxxxxx).
// =========================================================================================================================================
// =========================================================================================================================================
uuid_str_t uuid_format_z(const uuid_t uuid);
